// Astrologer Shreya banner in NBT and MT partner PDFs (hi/mr/en), asked for by NBT on 4 Nov 2026.
// Partner path only: the website report does not call this. Any other brand or language gets the html back unchanged.

const BANNER_LOGO_RE = /Partner-assets\/(Logo%20\(1\)\.png|TIL\/brands\/mt-astro\.(png|svg))$/;
const BANNER_LANGUAGES = ["hi", "mr", "en"];
const BANNER_LINK = "https://api.whatsapp.com/send/?phone=918377000287&text=Kundli%20Consultation";
const BANNER_IMG = "data:image/webp;base64,";
// Page 4 (Life Path), page 6 (Chemistry) and the last page (Disclaimer).
const BANNER_PAGES = [4, 6];

export function addShreyaBanner(
  html: string,
  language: string,
  branding: { logo_url?: unknown; cobrand?: unknown },
): string {
  const logo = typeof branding.logo_url === "string" ? branding.logo_url : "";
  if (branding.cobrand === true || !BANNER_LOGO_RE.test(logo) || !BANNER_LANGUAGES.includes(language)) return html;
  const parts = html.split('<div class="page');
  const last = parts.length - 1;
  if (last < 7) return html;
  const banner = `<a href="${BANNER_LINK}" target="_blank" rel="noopener" style="display:block;width:100%;margin:12px 0 0;">`
    + `<img src="${BANNER_IMG}" alt="Chat with Astrologer Shreya" style="display:block;width:100%;height:auto;border:0;"/></a>`;
  for (const n of [...BANNER_PAGES, last]) {
    const at = parts[n].lastIndexOf('<div class="frun');
    if (at < 0) return html;
    parts[n] = parts[n].slice(0, at) + banner + parts[n].slice(at);
  }
  return parts.join('<div class="page');
}
